/*
 * A072254  Numbers n such that triples generated by {2*(n-1),2*n,2*(n+1)}
 *          form A007534.
 * https://oeis.org/A072254
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(1)=1; for n>1, a(n) = n such that 2(n-1), 2n, 2(n+1) are all
 *            in A007534 (even numbers not the sum of two twin primes); found
 *            by sieve + search
 * Range:     u8 n <= 3, u16 n <= 12, u32 n <= 12, u64 n <= 12, u128 n <= 12,
 *            big any n
 * Validated: partial, pass, 12 terms through n = 12 (2026-11-07)
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <stdbool.h>
#include <stdlib.h>
#include <string.h>

#define A072254_LIMIT 3000000u

static uint64_t A072254_terms[1000];
static int A072254_cnt = 0;
static bool A072254_ready = false;

static void A072254_init(void) {
    uint32_t L = A072254_LIMIT;
    bool *comp = (bool *)calloc(L + 3, 1);
    bool *tw = (bool *)calloc(L + 3, 1);
    bool *nm = (bool *)calloc(L + 3, 1);
    uint32_t i, j, m, p;
    comp[0] = comp[1] = true;
    for (i = 2; (uint64_t)i * i <= L + 2; i++)
        if (!comp[i])
            for (j = i * i; j <= L + 2; j += i) comp[j] = true;
    for (i = 3; i + 2 <= L; i++)
        if (!comp[i] && !comp[i + 2]) { tw[i] = true; tw[i + 2] = true; }
    for (m = 2; m <= L; m += 2) {
        bool ok = false;
        for (p = 3; p * 2 <= m; p++) {
            if (tw[p] && tw[m - p]) { ok = true; break; }
        }
        if (!ok) nm[m] = true;
    }
    A072254_terms[A072254_cnt++] = 1;
    for (i = 2; 2 * (i + 1) <= L; i++) {
        if (nm[2 * (i - 1)] && nm[2 * i] && nm[2 * (i + 1)]) {
            if (A072254_cnt < 1000) A072254_terms[A072254_cnt++] = i;
        }
    }
    free(comp); free(tw); free(nm);
    A072254_ready = true;
}

seq_t a(idx_t n) {
    if (!A072254_ready) A072254_init();
    if (n < 1 || n > (idx_t)A072254_cnt) return 0;
    return (seq_t)A072254_terms[n - 1];
}
